# -*- coding: utf-8 -*-


class PlaywrightTafError(Exception):
    """Base exception for Playwright-backed TAF libraries."""


class PlaywrightDependencyMissing(PlaywrightTafError):
    """Raised when the Playwright Python package is unavailable."""


class UnsupportedBrowser(PlaywrightTafError):
    """Raised when a requested browser backend is not supported."""


class SessionNotFound(PlaywrightTafError):
    """Raised when an alias does not map to an active session."""


class DownloadNotFound(PlaywrightTafError):
    """Raised when a downloaded file cannot be resolved in time."""


class PageActionError(PlaywrightTafError):
    """Raised when a page action fails after fallback handling."""
